+		poly := new(Polygon)
+		switch version {
+		case encodingVersion:
+			poly.decode(d)
+		case encodingCompressedVersion:
+			poly.decodeCompressed(d)
+		default:
+			d.err = fmt.Errorf("unsupported polygon version %d", version)
+			return nil
+		}
+		return poly
+	case typeTagPolyline:
+		var poly Polyline
+		poly.decode(d)
+		return &poly
+	case typeTagPointVector:
+		var pv PointVector
+		pv.decode(d)
+		return &pv
+	case typeTagLaxPolyline:
+		lp := new(LaxPolyline)
+		lp.decode(d)
+		return lp
+	case typeTagLaxPolygon:
+		lp := new(LaxPolygon)
+		lp.decode(d)
+		return lp
+	case typeTagLoop:
+		l := new(Loop)
+		l.decode(d)
+		return l
+	case typeTagLaxLoop:
+		ll := new(LaxLoop)
+		ll.decode(d)
+		return ll
